-- Keep the same row boundaries, but evaluate session/role/event scopes once
-- per statement instead of once for every ledger/entry row.
begin;
create function private.finance_event_ids() returns setof bigint
language plpgsql stable security definer set search_path='' as $$
begin
 if not private.permission_actor_active() then return; end if;
 return query select c.id from public.calendar c where private.finance_event(c.id);
end $$;
create function private.own_payment_player_id() returns bigint
language sql stable security definer set search_path='' as $$
 select p.id from public.players p where lower(trim(p.email))=lower(auth.email()) and private.permission_actor_active() order by p.id limit 1
$$;
revoke all on function private.finance_event_ids(),private.own_payment_player_id() from public,anon,authenticated,service_role;
grant execute on function private.finance_event_ids(),private.own_payment_player_id() to authenticated;
alter policy security_exact_registration_read on public.event_registrations using ((select private.permission_actor_active()) and (event_id in (select private.finance_event_ids()) or lower(trim(email))=(select lower(auth.email())) or lower(trim(partner_email))=(select lower(auth.email())) or lower(trim(registered_by))=(select lower(auth.email()))));
alter policy security_exact_registration_update on public.event_registrations using ((select private.permission_actor_active()) and (event_id in (select private.finance_event_ids()) or lower(trim(email))=(select lower(auth.email())) or lower(trim(partner_email))=(select lower(auth.email())) or lower(trim(registered_by))=(select lower(auth.email())))) with check ((select private.permission_actor_active()) and (event_id in (select private.finance_event_ids()) or lower(trim(email))=(select lower(auth.email())) or lower(trim(partner_email))=(select lower(auth.email())) or lower(trim(registered_by))=(select lower(auth.email()))));
do $$begin if exists(select 1 from pg_policy where polrelid='public.event_registrations'::regclass and polname='Authenticated read own or admin registrations') then alter policy "Authenticated read own or admin registrations" on public.event_registrations using ((select private.permission_actor_active()) and (event_id in (select private.finance_event_ids()) or lower(trim(email))=(select lower(auth.email())) or lower(trim(partner_email))=(select lower(auth.email())) or lower(trim(registered_by))=(select lower(auth.email())))); end if; end $$;
do $$begin if exists(select 1 from pg_policy where polrelid='public.event_registrations'::regclass and polname='Authenticated update own or admin registrations') then alter policy "Authenticated update own or admin registrations" on public.event_registrations using ((select private.permission_actor_active()) and (event_id in (select private.finance_event_ids()) or lower(trim(email))=(select lower(auth.email())) or lower(trim(partner_email))=(select lower(auth.email())) or lower(trim(registered_by))=(select lower(auth.email())))) with check ((select private.permission_actor_active()) and (event_id in (select private.finance_event_ids()) or lower(trim(email))=(select lower(auth.email())) or lower(trim(partner_email))=(select lower(auth.email())) or lower(trim(registered_by))=(select lower(auth.email())))); end if; end $$;
alter policy security_exact_payment_read on public.payments using ((select private.permission_actor_active()) and (event_id in (select private.finance_event_ids()) or player_id=(select private.own_payment_player_id()) or lower(trim(metadata->>'email'))=(select lower(auth.email())) or lower(trim(metadata->>'registrant_email'))=(select lower(auth.email()))));
alter policy security_exact_payment_update on public.payments using ((select private.permission_actor_active()) and (event_id in (select private.finance_event_ids()) or player_id=(select private.own_payment_player_id()) or lower(trim(metadata->>'email'))=(select lower(auth.email())) or lower(trim(metadata->>'registrant_email'))=(select lower(auth.email())))) with check ((select private.permission_actor_active()) and (event_id in (select private.finance_event_ids()) or player_id=(select private.own_payment_player_id()) or lower(trim(metadata->>'email'))=(select lower(auth.email())) or lower(trim(metadata->>'registrant_email'))=(select lower(auth.email()))));
do $$begin if exists(select 1 from pg_policy where polrelid='public.payments'::regclass and polname='Authenticated read own payments') then alter policy "Authenticated read own payments" on public.payments using ((select private.permission_actor_active()) and (event_id in (select private.finance_event_ids()) or player_id=(select private.own_payment_player_id()) or lower(trim(metadata->>'email'))=(select lower(auth.email())) or lower(trim(metadata->>'registrant_email'))=(select lower(auth.email())))); end if; end $$;
do $$begin if exists(select 1 from pg_policy where polrelid='public.payments'::regclass and polname='Authenticated update own payments') then alter policy "Authenticated update own payments" on public.payments using ((select private.permission_actor_active()) and (event_id in (select private.finance_event_ids()) or player_id=(select private.own_payment_player_id()) or lower(trim(metadata->>'email'))=(select lower(auth.email())) or lower(trim(metadata->>'registrant_email'))=(select lower(auth.email())))) with check ((select private.permission_actor_active()) and (event_id in (select private.finance_event_ids()) or player_id=(select private.own_payment_player_id()) or lower(trim(metadata->>'email'))=(select lower(auth.email())) or lower(trim(metadata->>'registrant_email'))=(select lower(auth.email())))); end if; end $$;
alter policy security_scoped_registration_finance_read on public.event_registrations using (event_id in (select private.finance_event_ids()));
alter policy security_scoped_registration_finance_update on public.event_registrations using (event_id in (select private.finance_event_ids())) with check (event_id in (select private.finance_event_ids()));
alter policy security_scoped_payment_admin on public.payments using (event_id in (select private.finance_event_ids())) with check (event_id in (select private.finance_event_ids()));
alter policy security_exact_profile_read on public.players using ((select private.permission_actor_active()) and (lower(trim(email))=(select lower(auth.email())) or (select public.is_super_admin(auth.email())) or lower(email) in(select private.managed_event_player_emails())));
notify pgrst,'reload schema';
commit;
